"""Regenerate tests/fixtures/mock-data.js: a small `data` branch for the page's tests and stories.

Its newest run is a real ``sistent check`` report (scanner/tests/fixtures/sistent_report.json); the older runs are that
report with findings added, so that the history shows the fleet converging on main. Every record goes through the
scanner's own record and index code, so the fixture always has the shape the scan workflow produces.

    pip install -e scanner && python tests/fixtures/generate_mock_data.py
"""

from __future__ import annotations

import copy
import json
import tempfile
from pathlib import Path
from typing import Any

from sistence_scanner.config import ScanConfig
from sistence_scanner.discover import Resolved
from sistence_scanner.record import build_record
from sistence_scanner.store import INDEX_PATH, append_record, iter_records, write_index

HERE = Path(__file__).resolve().parent
REPORT = HERE.parents[1] / "scanner" / "tests" / "fixtures" / "sistent_report.json"
OUTPUT = HERE / "mock-data.js"
BASE_URL = "https://raw.githubusercontent.com/CodyCBakerPhD/sistence/data"

SATELLITES = ["CodyCBakerPhD/sistence", "dandi/usage-page"]


def extra_finding(repo: str, aspect: str, severity: str, n: int) -> dict[str, Any]:
    return {
        "id": f"synthetic{n:04d}",
        "candidate_key": f"synthetic{n:04d}",
        "aspect": aspect,
        "repo": repo,
        "kind": "missing",
        "subject": "key",
        "severity": severity,
        "direction": "downstream",
        "locator": f"synthetic.toml:key{n}",
        "message": f"key missing: key{n}",
        "detail": None,
        "detail_kind": None,
        "option": None,
        "content_key": f"key{n}",
        "suppressed": False,
        "baselined": False,
    }


def variant(report: dict[str, Any], timestamp: str, extra: list[tuple[str, str, str]]) -> dict[str, Any]:
    out = copy.deepcopy(report)
    out["generated_at"] = timestamp
    out["findings"].extend(extra_finding(repo, aspect, severity, n) for n, (repo, aspect, severity) in enumerate(extra))
    return out


def main() -> None:
    report = json.loads(REPORT.read_text(encoding="utf-8"))
    names = [status["name"] for status in [report["main"], *report["repos"]]]
    config = ScanConfig(organizations=(), repositories=tuple(names), main=report["main"]["name"])
    resolved = Resolved(
        main=config.main,
        repositories=config.repositories,
        skipped={"CodyCBakerPhD/old-fork": "fork"},
    )
    runs = [
        (
            "2026-09-01T12:00:00Z",
            [(r, a, "error") for r in SATELLITES for a in ("community_files", "pre_commit")],
        ),
        (
            "2026-09-15T12:00:00Z",
            [(r, "community_files", "warning") for r in SATELLITES],
        ),
        (
            "2026-10-01T09:30:00Z",
            [("CodyCBakerPhD/sistence", "community_files", "info")],
        ),
        ("2026-10-01T18:45:00Z", []),
        ("2026-10-17T02:13:45Z", []),
    ]
    with tempfile.TemporaryDirectory() as tmp:
        root = Path(tmp)
        for n, (timestamp, extra) in enumerate(runs):
            run_url = f"https://github.com/CodyCBakerPhD/sistence/actions/runs/{1000 + n}"
            record = build_record(
                variant(report, timestamp, extra),
                config=config,
                resolved=resolved,
                run_url=run_url,
            )
            append_record(root, record)
        write_index(root)
        files = {str(path): (root / path).read_text(encoding="utf-8") for path, _, _ in iter_records(root)}
        index = (root / INDEX_PATH).read_text(encoding="utf-8")

    lines = [
        "// Generated by tests/fixtures/generate_mock_data.py; regenerate rather than edit.",
        "// A small `data` branch: the index and every report file, as the scan workflow writes them.",
        "",
        f"export const BASE_URL = {json.dumps(BASE_URL)};",
        "",
        f"export const INDEX_JSON = {json.dumps(index)};",
        "",
        "/** Report files by their path on the `data` branch, as JSON Lines text. */",
        f"export const REPORT_FILES = {json.dumps(dict(sorted(files.items())), indent=4)};",
        "",
        "export const INDEX = JSON.parse(INDEX_JSON);",
        "",
        "/** The record of one run of the index. */",
        "export function record_of(run) {",
        '    return JSON.parse(REPORT_FILES[run.file].split("\\n")[run.line - 1]);',
        "}",
        "",
        "export const LATEST_RUN = INDEX.runs[INDEX.runs.length - 1];",
        "export const LATEST_RECORD = record_of(LATEST_RUN);",
        "",
    ]
    OUTPUT.write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {OUTPUT.relative_to(HERE.parents[1])}: {len(runs)} runs in {len(files)} report files")


if __name__ == "__main__":
    main()
